mapper.select:
SELECT i.*
FROM iws_process_instance i
WHERE i.id = #{instanceId}

SELECT a.*
FROM iws_process_action_audit a
JOIN iws_process_instance i
  ON i.id = COALESCE(a.instance_id, a.child_instance_id, a.supervisor_instance_id)
WHERE 1 = 1

  AND i.business_schedule_code = #{q.businessScheduleCode}


  AND (a.instance_id = #{q.instanceId} OR a.child_instance_id = #{q.instanceId}
       OR a.supervisor_instance_id = #{q.instanceId})


  AND a.event_id = #{q.eventId}


  AND (a.actor_name LIKE CONCAT('%', #{q.operator}, '%')
       OR a.actor_user_id LIKE CONCAT('%', #{q.operator}, '%'))


  AND a.action_code = #{q.action}


  AND a.result = #{q.result}


  AND a.occurred_at >= #{q.occurredFrom}


  AND a.occurred_at <= #{q.occurredTo}

ORDER BY a.occurred_at DESC, a.id DESC
